    @Test
    void rootHasNoChild() {
        Node root = new CompilationUnit();
        List<Node> nodes = root.findAll(Node.class, Node.TreeTraversal.PREORDER);
        assertEquals(Arrays.asList(CompilationUnit.class), classesOf(nodes));
    }

